size_t PAGE = 4096;
void *ptr = mmap(NULL, PAGE, PROT_RW,
                 MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

// Prerequisite: Lock memory first
mlock(ptr, PAGE);

const void *addr = ptr;
size_t len = PAGE;

// Unlock the specified address range
// Pages containing this range become swappable
int ret = munlock(addr, len);

if (ret == -1) {
    // Check errno for EAGAIN (resource limits exceeded)
    // or EINVAL (misaligned parameters)
}

munmap(ptr, PAGE);
